62		cmd.Flags().BoolVar(&f.noGraph, "no-graph", false, "Skip the graph-derived blast-radius section")
63		cmd.Flags().Bool("json", false, "Shorthand for --format json")
64		return cmd
65	}
66	
67	func runHandoff(ctx context.Context, out io.Writer, f *handoffFlags) error {
68		repo, err := gitrepo.OpenCurrent(ctx)
69		if err != nil {
70			return fmt.Errorf("open repository: %w", err)
71		}
72		defer repo.Close()
73	
74		stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{
75			BlobFetcher: FetchBlobsByHash,
76			RefFetcher:  FetchCheckpointRef,
77			ReadRemotes: strategy.CheckpointReadRemotes(ctx),
78		})
79		if err != nil {
80			return fmt.Errorf("open checkpoint store: %w", err)
81		}
82	
83		in, err := handoff.Load(ctx, stores.Persistent, handoff.LoadOptions{
84			Repo:       handoffRepoName(ctx),
85			Head:       handoffHeadCheckpoint(ctx, repo),
86			Limit:      f.limit,
87			Checkpoint: f.checkpoint,
88		})
89		if err != nil {
90			return fmt.Errorf("read checkpoints: %w", err)
91		}
92	
93		packet := handoff.Build(ctx, in, f.noGraph)
94	
95		if f.format == handoffFormatJSON {
96			if err := handoff.RenderJSON(out, packet); err != nil {
97				return fmt.Errorf("render packet: %w", err)
98			}
99			return nil
100		}
101		if err := handoff.RenderMarkdown(out, packet); err != nil {
102			return fmt.Errorf("render packet: %w", err)
103		}
104		return nil
105	}
106	
107	// handoffRepoName identifies the repo for the packet header.
108	//
109	// Resolved from the origin remote, falling back to the worktree's base name.
110	// Deliberately local-only: currentRepoRef would answer more precisely but calls
111	// the control plane, and a handoff must still build offline.
112	func handoffRepoName(ctx context.Context) string {
113		forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
114		if err == nil && owner != "" && repo != "" {
115			if forge != "" {
116				return fmt.Sprintf("%s/%s/%s", forge, owner, repo)
117			}
118			return owner + "/" + repo
119		}
120		if root, err := paths.WorktreeRoot(ctx); err == nil {
121			return "local/" + filepath.Base(root)
122		}
123		return "local"
124	}
125	
126	// handoffHeadCheckpoint returns the checkpoint ID on HEAD's Entire-Checkpoint
127	// trailer, or "" when HEAD carries none. Absence is normal -- the working tree
128	// may simply be ahead of the last checkpointed commit -- so it is never an error.
129	func handoffHeadCheckpoint(_ context.Context, repo *git.Repository) string {
130		head, err := repo.Head()
131		if err != nil {
132			return ""
133		}
134		commit, err := repo.CommitObject(head.Hash())
135		if err != nil {
136			return ""
137		}
138		if cpID, ok := trailers.ParseCheckpoint(commit.Message); ok {
139			return cpID.String()
140		}
141		return ""
142	}

