2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"net/url"
12		"os"
13		"path"
14		"path/filepath"
15		"strings"
16		"time"
17	)
18	
19	const (
20		filesAPIPath      = "/api/2.0/fs/files"
21		statementsAPIPath = "/api/2.0/sql/statements"
22		localHostScheme   = "file://"
23		requestTimeout    = 60 * time.Second
24	)
25	
26	type Config struct {
27		Host        string
28		Token       string
29		WarehouseID string
30		VolumePath  string
31		Table       string
32	}
33	
34	func ConfigFromEnv() (Config, error) {
35		c := Config{
36			Host:        strings.TrimSpace(os.Getenv("DATABRICKS_HOST")),
37			Token:       strings.TrimSpace(os.Getenv("DATABRICKS_TOKEN")),
38			WarehouseID: strings.TrimSpace(os.Getenv("DATABRICKS_WAREHOUSE_ID")),
39			VolumePath:  strings.TrimSpace(os.Getenv("DATABRICKS_VOLUME_PATH")),
40			Table:       strings.TrimSpace(os.Getenv("DATABRICKS_TABLE")),
41		}
42		if c.Table == "" {
43			c.Table = "handoff_packets"
44		}
45		if c.Host == "" {
46			return c, errors.New("DATABRICKS_HOST is required (use file:///path for local output)")
47		}
48		if c.IsLocal() {
49			return c, nil
50		}
51		if c.Token == "" {
52			return c, errors.New("DATABRICKS_TOKEN is required when DATABRICKS_HOST is a workspace URL")
53		}
54		if c.VolumePath == "" {
55			return c, errors.New("DATABRICKS_VOLUME_PATH is required when DATABRICKS_HOST is a workspace URL")
56		}
57		return c, nil
58	}
59	
60	func (c Config) IsLocal() bool { return strings.HasPrefix(c.Host, localHostScheme) }
61	
62	func (c Config) LocalDir() string { return strings.TrimPrefix(c.Host, localHostScheme) }
63	
64	type Uploader struct {
65		cfg    Config
66		client *http.Client
67	}
68	
69	func NewUploader(cfg Config) *Uploader {
70		return &Uploader{cfg: cfg, client: &http.Client{Timeout: requestTimeout}}
71	}
72	
73	func objectName(p Packet, now time.Time) string {
74		head := p.Head
75		if head == "" {
76			head = "nohead"
77		}
78		return fmt.Sprintf("%s-%d.json", sanitizeSegment(head), now.UTC().UnixNano())
79	}
80	
81	func sanitizeSegment(s string) string {
82		var b strings.Builder
83		for _, r := range s {
84			switch {
85			case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '-', r == '_':
86				b.WriteRune(r)
87			default:
88				b.WriteByte('-')
89			}
90		}
91		out := strings.Trim(b.String(), "-")
92		if out == "" {
93			return "unknown"
94		}
95		return out
96	}
97	
98	func (u *Uploader) Upload(ctx context.Context, p Packet, payload []byte, now time.Time) (string, error) {
99		name := objectName(p, now)
100		repoDir := sanitizeSegment(p.Repo)
101	
102		if u.cfg.IsLocal() {
103			dir := filepath.Join(u.cfg.LocalDir(), repoDir)
104			if err := os.MkdirAll(dir, 0o750); err != nil {
105				return "", fmt.Errorf("create local output dir: %w", err)
106			}
107			dest := filepath.Join(dir, name)
108			if err := os.WriteFile(dest, payload, 0o600); err != nil {
109				return "", fmt.Errorf("write local output: %w", err)
110			}
111			return dest, nil
112		}
113	
114		remote := path.Join(u.cfg.VolumePath, repoDir, name)
115		endpoint, err := u.endpoint(filesAPIPath + ensureLeadingSlash(remote))
116		if err != nil {
117			return "", err
118		}
119		req, err := http.NewRequestWithContext(ctx, http.MethodPut, endpoint, bytes.NewReader(payload))
120		if err != nil {
121			return "", fmt.Errorf("build upload request: %w", err)
122		}
123		req.Header.Set("Authorization", "Bearer "+u.cfg.Token)
124		req.Header.Set("Content-Type", "application/octet-stream")
125	
126		resp, err := u.client.Do(req)
127		if err != nil {
128			return "", fmt.Errorf("upload to volume: %w", err)
129		}
130		defer resp.Body.Close()
131		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
132			return "", fmt.Errorf("upload to volume: %s: %s", resp.Status, readSnippet(resp.Body))
133		}
134		return remote, nil
135	}
136	
137	func (u *Uploader) CopyInto(ctx context.Context, remotePath string) error {
138		if u.cfg.IsLocal() {
139			return nil
140		}
141		if u.cfg.WarehouseID == "" {
142			return errors.New("DATABRICKS_WAREHOUSE_ID is required to run COPY INTO")
143		}
144	
145		stmt := fmt.Sprintf(
146			"COPY INTO %s FROM '%s' FILEFORMAT = JSON FORMAT_OPTIONS ('inferTimestamp' = 'true') COPY_OPTIONS ('mergeSchema' = 'false')",
147			u.cfg.Table, path.Dir(ensureLeadingSlash(remotePath)),
148		)
149		body, err := json.Marshal(map[string]any{
150			"statement":    stmt,
151			"warehouse_id": u.cfg.WarehouseID,
152			"wait_timeout": "30s",
153		})
154		if err != nil {
155			return fmt.Errorf("encode statement request: %w", err)
156		}
157		endpoint, err := u.endpoint(statementsAPIPath)
158		if err != nil {
159			return err
160		}
161		req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
162		if err != nil {
163			return fmt.Errorf("build statement request: %w", err)
164		}
165		req.Header.Set("Authorization", "Bearer "+u.cfg.Token)
166		req.Header.Set("Content-Type", "application/json")
167	
168		resp, err := u.client.Do(req)
169		if err != nil {
170			return fmt.Errorf("copy into: %w", err)
171		}
172		defer resp.Body.Close()
173		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
174			return fmt.Errorf("copy into: %s: %s", resp.Status, readSnippet(resp.Body))
175		}
176		return nil
177	}
178	
179	func (u *Uploader) endpoint(p string) (string, error) {
180		base, err := url.Parse(strings.TrimSuffix(u.cfg.Host, "/"))
181		if err != nil {
182			return "", fmt.Errorf("parse DATABRICKS_HOST: %w", err)
183		}
184		if base.Scheme != "https" && base.Host != "127.0.0.1" && !strings.HasPrefix(base.Host, "127.0.0.1:") {
185			return "", errors.New("DATABRICKS_HOST must use https")
186		}
187		return base.String() + p, nil
188	}
189	
190	func ensureLeadingSlash(p string) string {
191		if strings.HasPrefix(p, "/") {
192			return p
193		}
194		return "/" + p
195	}
196	
197	func readSnippet(r io.Reader) string {
198		b, err := io.ReadAll(io.LimitReader(r, 512))
199		if err != nil {
200			return ""
201		}
202		return strings.TrimSpace(string(b))
203	}

