3	// allExtractors is the wiring list: it names every extractor exactly once, in
4	// packet order.
5	//
6	// This file is written once and then never edited again. Each workstream
7	// implements its own constructor in its own file and deletes the matching stub
8	// in stubs.go, so no shared file is ever changed twice and the wiring cannot
9	// conflict during integration. Adding a section -- including one a curveball
10	// demands -- is a new file plus one stub deletion.
11	type BuildOptions struct {
12		NoGraph  bool
13		Searcher VectorSearcher
14		Ask      string
15	}
