17	func allExtractors(opts BuildOptions) []Extractor {
18		xs := []Extractor{
19			newIntentExtractor(),
20			newOpenItemsExtractor(),
21			newDeadEndsExtractor(),
22		}
23		if !noGraph(opts) {
24			xs = append(xs, newSurfaceExtractor())
25		}
