1	package handoff
2	
3	import (
4		"context"
5		"fmt"
6		"sort"
7		"time"
8	
9		apicheckpoint "github.com/entireio/cli/api/checkpoint"
10		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
11	)
12	
13	// Store is the slice of the checkpoint store this package needs. Narrowing it
14	// to three methods keeps the extractors testable with a small fake instead of a
15	// real git repository.
16	type Store interface {
17		List(ctx context.Context) ([]apicheckpoint.CheckpointInfo, error)
18		Read(ctx context.Context, checkpointID id.CheckpointID) (*apicheckpoint.CheckpointSummary, error)
19		ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*apicheckpoint.SessionContent, error)
20	}
21	
22	// LoadOptions bounds the checkpoint walk.
23	type LoadOptions struct {
24		Repo       string
25		Head       string
26		Limit      int    // max checkpoints; <= 0 means DefaultLimit
27		Checkpoint string // start here instead of the newest
28		Session    string // only checkpoints from this session id
29		Graph      GraphRunner
30	}
31	
32	// DefaultLimit is how many checkpoints back we read when unbounded. Ten covers
33	// a working session without making the packet too long for an agent to act on.
34	const DefaultLimit = 10
35	
36	const (
37		LoadBudget       = 10 * time.Second
38		minLoadAttempts  = 20
39		loadAttemptScale = 3
40	)
41	
42	// Load walks the store newest-first and assembles the Input.
43	//
44	// Per-checkpoint failures are skipped rather than fatal: a single unreadable
45	// checkpoint -- unpushed, pruned, or written by a newer CLI -- must not deny
46	// the caller the other nine.
47	func Load(ctx context.Context, store Store, opts LoadOptions) (Input, error) {
48		in := Input{Repo: opts.Repo, Head: opts.Head, Graph: opts.Graph}
49	
50		infos, err := store.List(ctx)
51		if err != nil {
52			return in, fmt.Errorf("list checkpoints: %w", err)
53		}
54		// List order is not guaranteed; the whole contract is newest-first.
55		sort.Slice(infos, func(i, j int) bool {
56			return infos[i].CreatedAt.After(infos[j].CreatedAt)
57		})
58	
59		if opts.Checkpoint != "" {
60			infos = skipUntil(infos, opts.Checkpoint)
61		}
62	
63		limit := opts.Limit
64		if limit <= 0 {
65			limit = DefaultLimit
66		}
67	
68		deadline := Now().Add(LoadBudget)
69		maxAttempts := limit * loadAttemptScale
70		if maxAttempts < minLoadAttempts {
71			maxAttempts = minLoadAttempts
72		}
73		attempts := 0
74	
75		for _, info := range infos {
76			if len(in.Checkpoints) >= limit {
77				break
78			}
79			if ctx.Err() != nil || attempts >= maxAttempts || Now().After(deadline) {
80				in.Truncated = true
81				break
82			}
83			if opts.Session != "" && !checkpointHasSession(info, opts.Session) {
84				continue
85			}
86			attempts++
87			in.Listed++
88			if info.ListedStub {
89				in.Unreadable++
90				// Names-only remote-discovery entry with nothing hydrated behind it.
91				continue
92			}
93			cp, ok := loadCheckpoint(ctx, store, info)
94			if !ok {
95				in.Unreadable++
96				continue
97			}
98			in.Checkpoints = append(in.Checkpoints, cp)
99		}
100		return in, nil
101	}
102	
103	// loadCheckpoint reads one checkpoint's session data. Reports false when there
104	// is nothing usable to contribute.
105	func loadCheckpoint(ctx context.Context, store Store, info apicheckpoint.CheckpointInfo) (Checkpoint, bool) {
106		// Session 0 is the primary session; a checkpoint always has at least one.
107		content, err := store.ReadSessionContent(ctx, info.CheckpointID, 0)
108		if err != nil || content == nil {
109			return Checkpoint{}, false
110		}
111		md := content.Metadata
112	
113		cp := Checkpoint{
114			ID:           info.CheckpointID.String(),
115			SessionIndex: 0,
116			CreatedAt:    info.CreatedAt,
117			Metadata:     &md,
118			Summary:      md.Summary,
119			FilesTouched: info.FilesTouched,
120			Transcript:   content.Transcript,
121		}
122		if len(cp.FilesTouched) == 0 {
123			cp.FilesTouched = md.FilesTouched
124		}
125	
126		// Resolve the compact-transcript offset exactly once here so no extractor
127		// calls it twice and none reaches for GetTranscriptStart(), which indexes a
128		// different file in a different coordinate system.
129		cp.CompactStart, cp.HasCompactStart = md.GetCompactTranscriptStart()
130	
131		return cp, true
132	}
133	
134	// skipUntil drops entries newer than the requested checkpoint, so --checkpoint
135	// reads "start the handoff here". An unknown ID yields the full list rather
136	// than an empty one: showing everything is a recoverable surprise, showing
137	// nothing looks like data loss.
138	func skipUntil(infos []apicheckpoint.CheckpointInfo, want string) []apicheckpoint.CheckpointInfo {
139		for i, info := range infos {
140			if info.CheckpointID.String() == want {
141				return infos[i:]
142			}
143		}
144		return infos
145	}
146	
147	func checkpointHasSession(info apicheckpoint.CheckpointInfo, want string) bool {
148		if info.SessionID == want {
149			return true
150		}
151		for _, id := range info.SessionIDs {
152			if id == want {
153				return true
154			}
155		}
156		return false
157	}

