		t.Fatalf("Extract: %v", err)
	}
	c := sec.Items[0].Cites[0]
	if c.CheckpointID != "01PRIOR" || c.SessionIndex != 2 || c.Line != 412 {
		t.Errorf("retrieval lost provenance: %+v", c)
