1	package handoff
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"net/http"
9		"os"
10		"strings"
11		"time"
12	)
13	
14	const (
15		SectionGlobalMemory = "prior_art"
16	
17		vectorQueryTimeout = 20 * time.Second
18		vectorNumResults   = 5
19		maxQueryTextChars  = 400
20	)
21	
22	type VectorSearcher interface {
23		Query(ctx context.Context, text string, numResults int) ([]PriorHit, error)
24	}
25	
26	type PriorHit struct {
27		RepoKey      string
28		CheckpointID string
29		SessionID    int
30		SectionName  string
31		ItemText     string
32		CiteLine     int
33		Score        float64
34	}
35	
36	type VectorConfig struct {
37		Host  string
38		Token string
39		Index string
40	}
41	
42	func VectorConfigFromEnv() (VectorConfig, bool) {
43		c := VectorConfig{
44			Host:  strings.TrimSpace(os.Getenv("DATABRICKS_HOST")),
45			Token: strings.TrimSpace(os.Getenv("DATABRICKS_TOKEN")),
46			Index: strings.TrimSpace(os.Getenv("DATABRICKS_VECTOR_INDEX")),
47		}
48		if c.Host == "" || c.Token == "" || c.Index == "" {
49			return c, false
50		}
51		if !strings.HasPrefix(c.Host, "https://") {
52			return c, false
53		}
54		return c, true
55	}
56	
57	type restVectorSearcher struct {
58		cfg    VectorConfig
59		client *http.Client
60	}
61	
62	func NewVectorSearcher(cfg VectorConfig) VectorSearcher {
63		return &restVectorSearcher{cfg: cfg, client: &http.Client{Timeout: vectorQueryTimeout}}
64	}
65	
66	type vectorQueryRequest struct {
67		Columns     []string `json:"columns"`
68		QueryText   string   `json:"query_text"`
69		NumResults  int      `json:"num_results"`
70		FiltersJSON string   `json:"filters_json,omitempty"`
71	}
72	
73	type vectorQueryResponse struct {
74		Manifest struct {
75			Columns []struct {
76				Name string `json:"name"`
77			} `json:"columns"`
78		} `json:"manifest"`
79		Result struct {
80			DataArray [][]any `json:"data_array"`
81		} `json:"result"`
82	}
83	
84	var priorArtColumns = []string{
85		"repo_key", "checkpoint_id", "session_id", "section_name", "item_text", "cite_line",
86	}
87	
88	func (s *restVectorSearcher) Query(ctx context.Context, text string, numResults int) ([]PriorHit, error) {
89		body, err := json.Marshal(vectorQueryRequest{
90			Columns:     priorArtColumns,
91			QueryText:   text,
92			NumResults:  numResults,
93			FiltersJSON: `{"section_name": "dead_ends"}`,
94		})
95		if err != nil {
96			return nil, fmt.Errorf("encode vector query: %w", err)
97		}
98	
99		endpoint := fmt.Sprintf("%s/api/2.0/vector-search/indexes/%s/query",
100			strings.TrimSuffix(s.cfg.Host, "/"), s.cfg.Index)
101	
102		req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
103		if err != nil {
104			return nil, fmt.Errorf("build vector query: %w", err)
105		}
106		req.Header.Set("Authorization", "Bearer "+s.cfg.Token)
107		req.Header.Set("Content-Type", "application/json")
108	
109		resp, err := s.client.Do(req)
110		if err != nil {
111			return nil, fmt.Errorf("vector query: %w", err)
112		}
113		defer resp.Body.Close()
114		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
115			return nil, fmt.Errorf("vector query: %s", resp.Status)
116		}
117	
118		var out vectorQueryResponse
119		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
120			return nil, fmt.Errorf("decode vector response: %w", err)
121		}
122		return hitsFrom(out), nil
123	}
124	
125	func hitsFrom(out vectorQueryResponse) []PriorHit {
126		idx := make(map[string]int, len(out.Manifest.Columns))
127		for i, c := range out.Manifest.Columns {
128			idx[c.Name] = i
129		}
130	
131		hits := make([]PriorHit, 0, len(out.Result.DataArray))
132		for _, row := range out.Result.DataArray {
133			get := func(name string) any {
134				i, ok := idx[name]
135				if !ok || i >= len(row) {
136					return nil
137				}
138				return row[i]
139			}
140			h := PriorHit{
141				RepoKey:      asString(get("repo_key")),
142				CheckpointID: asString(get("checkpoint_id")),
143				SessionID:    asInt(get("session_id")),
144				SectionName:  asString(get("section_name")),
145				ItemText:     asString(get("item_text")),
146				CiteLine:     asInt(get("cite_line")),
147			}
148			if h.ItemText == "" || h.CheckpointID == "" {
149				continue
150			}
151			hits = append(hits, h)
152		}
153		return hits
154	}
155	
156	func asString(v any) string {
157		s, ok := v.(string)
158		if !ok {
159			return ""
160		}
161		return strings.TrimSpace(s)
162	}
163	
164	func asInt(v any) int {
165		switch n := v.(type) {
166		case float64:
167			return int(n)
168		case string:
169			var out int
170			if _, err := fmt.Sscanf(n, "%d", &out); err == nil {
171				return out
172			}
173		}
174		return 0
175	}
176	
177	type globalMemoryExtractor struct {
178		searcher VectorSearcher
179		ask      string
180	}
181	
182	func newGlobalMemoryExtractor(s VectorSearcher, ask string) Extractor {
183		return globalMemoryExtractor{searcher: s, ask: ask}
184	}
185	
186	func (globalMemoryExtractor) Name() string { return SectionGlobalMemory }
187	
188	func (g globalMemoryExtractor) Extract(ctx context.Context, in Input) (Section, error) {
189		if g.searcher == nil {
190			return section(SectionGlobalMemory, nil, "vector search not configured"), nil
191		}
192	
193		query := strings.TrimSpace(g.ask)
194		if query == "" {
195			query = queryTextFrom(in)
196		}
197		if query == "" {
198			return section(SectionGlobalMemory, nil, "nothing to search on: no intent in range and no --ask given"), nil
199		}
200	
201		hits, err := g.searcher.Query(ctx, truncate(query, maxQueryTextChars), vectorNumResults)
202		if err != nil {
203			return section(SectionGlobalMemory, nil, fmt.Sprintf("vector search unavailable: %v", err)), nil
204		}
205		if len(hits) == 0 {
206			return section(SectionGlobalMemory, nil, "no prior work found for this task"), nil
207		}
208	
209		items := make([]Item, 0, len(hits))
210		for _, h := range hits {
211			items = append(items, Item{
212				Text: describeHit(h, in.Repo),
213				Cites: []Citation{{
214					CheckpointID: h.CheckpointID,
215					SessionIndex: h.SessionID,
216					Line:         h.CiteLine,
217				}},
218			})
219		}
220		return Section{
221			Name:  SectionGlobalMemory,
222			Items: items,
223			Note:  "retrieved by similarity across the team's history; verify before relying on it",
224		}, nil
225	}
226	
227	func describeHit(h PriorHit, currentRepo string) string {
228		if h.RepoKey != "" && h.RepoKey != currentRepo {
229			return fmt.Sprintf("[%s] %s", h.RepoKey, h.ItemText)
230		}
231		return h.ItemText
232	}
233	
234	func queryTextFrom(in Input) string {
235		var parts []string
236		for _, cp := range in.Checkpoints {
237			if cp.Summary == nil {
238				continue
239			}
240			if s := strings.TrimSpace(cp.Summary.Intent); s != "" {
241				parts = append(parts, s)
242			}
243			if len(parts) >= 2 {
244				break
245			}
246		}
247		return strings.Join(parts, " ")
248	}
